package helps

import (
	"context"
	"encoding/binary"
	"io"
	"net"
	"reflect"
	"testing"
	"time"

	utls "github.com/refraction-networking/utls"
)

func TestCodexWebsocketTLSRustlsExtensionOrder(t *testing.T) {
	// Generated by compiling the unmodified sorting/hash functions from the
	// checksum-verified rustls 0.23.45 crate pinned by Codex rust-v0.163.0.
	cases := []struct {
		name string
		seed uint16
		want []uint16
	}{
		{"zero", 0, []uint16{5, 43, 11, 10, 0, 13, 35, 23, 51, 45}},
		{"one", 1, []uint16{10, 45, 13, 0, 43, 23, 5, 35, 11, 51}},
		{"1234", 0x1234, []uint16{35, 51, 10, 23, 0, 43, 13, 5, 45, 11}},
		{"abcd", 0xabcd, []uint16{13, 0, 51, 10, 43, 23, 35, 11, 45, 5}},
		{"maximum", 65535, []uint16{13, 5, 11, 10, 45, 23, 43, 51, 0, 35}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			client, server := net.Pipe()
			defer client.Close()
			captured := make(chan []byte, 1)
			go func() {
				defer server.Close()
				header := make([]byte, 5)
				if _, err := io.ReadFull(server, header); err != nil {
					captured <- nil
					return
				}
				body := make([]byte, binary.BigEndian.Uint16(header[3:]))
				if _, err := io.ReadFull(server, body); err != nil {
					captured <- nil
					return
				}
				captured <- body
			}()
			conn := utls.UClient(client, codexFreshTLSConfig(&utls.Config{ServerName: "chatgpt.com"}), utls.HelloCustom)
			if err := conn.ApplyPreset(codexWebsocketHelloWithOrderSeed(tc.seed)); err != nil {
				t.Fatal(err)
			}
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			_ = conn.HandshakeContext(ctx)
			body := <-captured
			if len(body) < 39 {
				t.Fatalf("missing ClientHello: %d bytes", len(body))
			}
			b := body[4+2+32:]
			b = b[1+int(b[0]):]
			b = b[2+int(binary.BigEndian.Uint16(b)):]
			b = b[1+int(b[0]):]
			length := int(binary.BigEndian.Uint16(b))
			b = b[2 : 2+length]
			var got []uint16
			for len(b) > 0 {
				got = append(got, binary.BigEndian.Uint16(b))
				size := int(binary.BigEndian.Uint16(b[2:]))
				b = b[4+size:]
			}
			if !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("seed %d: wire extension order %v, want rustls %v", tc.seed, got, tc.want)
			}
		})
	}
}
